// Общие шаги для тестов формы «יצירת קשר עם המוכר» в дискретном объявлении (#3f0a85).
// Прод. Гость: «שלח הודעה» у гостя ничего не отправляет (0 не-GET) — только черновик и переход на /auth.
// Вошедший: «שלח הודעה» НЕ нажимать никогда (реальное сообщение чужому продавцу). Все не-GET/HEAD/OPTIONS
// запросы отклоняются — надёжно только в Chromium, поэтому тесты только @desktop / @android.
import { expect, Locator, Page } from '@playwright/test';
import * as fs from 'fs';
import * as path from 'path';

/** Реальное дискретное объявление (чужое) — только до открытой формы, без отправки от вошедшего. */
export const DISCREET_ID = '4a91620b-b4ef-4785-bb20-d0d40a67f977';
export const DISCREET_URL = `/businessdetail?id=${DISCREET_ID}`;
/** Обычное объявление — для черновика «от другого объявления». */
export const OTHER_ID = '4d62fda8-629a-4ad5-9913-3f925cbbb1d1';
export const DRAFT_KEY = 'b4s_contact_draft';
export const LOAD = { timeout: 20_000 };
const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

export const QA_FIELDS = {
  name: 'QA-AUTO',
  phone: '0500000000',
  email: 'qa-auto@example.com',
  message: 'QA-AUTO בדיקת טיוטה',
};

/**
 * Блок записи + cookie «только необходимые» (без клика по баннеру). Вызывать до первого перехода.
 * Запросы Google OAuth / authorize обрываются.
 */
export async function prepareReadOnly(page: Page) {
  await page.route('**/*', (route) => {
    const req = route.request();
    if (/accounts\.google\.com|\/auth\/v1\/authorize/.test(req.url())) return route.abort('blockedbyclient');
    return SAFE_METHODS.includes(req.method()) ? route.fallback() : route.abort('blockedbyclient');
  });
  await page.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

/**
 * Сессия user должна быть живой: обновление токена — POST, а он заблокирован.
 * Истекла → это ОКРУЖЕНИЕ: пользователь запускает `npm run qa-login:manual -- user` (или qa-login).
 */
export function assertUserSessionFresh() {
  const file = path.resolve(__dirname, '../../../auth/user.json');
  const state = JSON.parse(fs.readFileSync(file, 'utf8'));
  let expiresAt = 0;
  for (const o of state.origins ?? []) {
    for (const i of o.localStorage ?? []) {
      if (/-auth-token$/.test(i.name)) {
        try { expiresAt = JSON.parse(i.value).expires_at ?? 0; } catch {}
      }
    }
  }
  expect(expiresAt * 1000, 'сессия .qa/auth/user.json истекла — ОКРУЖЕНИЕ: обнови вход (qa-login), тест не трогать')
    .toBeGreaterThan(Date.now() + 2 * 60_000);
}

/**
 * Имитация возврата после входа: черновик в sessionStorage до загрузки страницы — ровно такой,
 * какой пишет сайт при гостевой отправке (CONTACT-AUTH-08). Кладётся один раз за вкладку,
 * чтобы обновление страницы его не возвращало.
 */
export async function seedDraft(page: Page, draft: { businessId: string; ageMs?: number }) {
  await page.addInitScript(
    ([key, businessId, ageMs, fields]) => {
      try {
        if (sessionStorage.getItem('qa_auto_draft_seeded')) return;
        sessionStorage.setItem('qa_auto_draft_seeded', '1');
        sessionStorage.setItem(key, JSON.stringify({ businessId, fields, at: Date.now() - ageMs }));
      } catch {}
    },
    [DRAFT_KEY, draft.businessId, draft.ageMs ?? 0, QA_FIELDS] as const,
  );
}

export const readDraft = (page: Page) =>
  page.evaluate((k) => {
    const v = sessionStorage.getItem(k);
    return v ? (JSON.parse(v) as { businessId: string; fields: Record<string, string>; at: number }) : null;
  }, DRAFT_KEY);

export const readRedirectAfterLogin = (page: Page) =>
  page.evaluate(() => sessionStorage.getItem('redirectAfterLogin'));

/** Форма «יצירת קשר עם המוכר». */
export const contactForm = (page: Page) => page.getByRole('dialog').filter({ hasText: 'יצירת קשר עם המוכר' });

export const fields = (form: Locator) => ({
  name: form.getByLabel('שם מלא'),
  phone: form.getByLabel('טלפון'),
  email: form.getByLabel('אימייל'),
  message: form.getByLabel(/הודעה/),
});

export async function fillQaFields(form: Locator) {
  const f = fields(form);
  await f.name.fill(QA_FIELDS.name);
  await f.phone.fill(QA_FIELDS.phone);
  await f.email.fill(QA_FIELDS.email);
  await f.message.fill(QA_FIELDS.message);
}

/**
 * Форма НЕ открылась сама. В положительном случае (CONTACT-AUTH-10) она появляется
 * в первые секунды после кнопки «שלח הודעה למוכר»; окно наблюдения — то же ожидание,
 * что и в положительной проверке, только с обратным результатом.
 */
export async function expectFormStaysClosed(page: Page, windowMs = 6_000) {
  await expect(page.getByRole('button', { name: 'שלח הודעה למוכר' }).first()).toBeVisible(LOAD);
  const opened = await contactForm(page)
    .waitFor({ state: 'visible', timeout: windowMs })
    .then(() => true, () => false);
  expect(opened, 'форма «יצירת קשר עם המוכר» сама не открылась').toBe(false);
}
